class ArrayStats {
  int[] a;
  ArrayStats(int[] x) {
    a = x;
  }
  int largest() {
    int big = a[0];
    for (int i = 1; i < a.length; i++) {
      if (a[i] > big) {
        big = a[i];
      }
    }
    return big;
  }
  double mean() {
    int s = 0;
    for (int i = 0; i < a.length; i++) {
      s += a[i];
    }
    return (double) s / a.length;
  }
  public static void main(String[] args) {
    int[] v = {34, 43, 16, 10};
    ArrayStats x = new ArrayStats(v);
    System.out.println(x.largest());
    System.out.println(x.mean());
  }
}
