class WordCount {
  String word;
  int vowels;
  WordCount(String w) {
    word = w;
    vowels = 0;
  }
  void count() {
    for (int i = 0; i < word.length(); i++) {
      char c = word.charAt(i);
      if (c == 'A' || c == 'E' || c == 'I' || c == 'O' || c == 'U') {
        vowels++;
      }
    }
  }
  void display() {
    System.out.println(word + " has " + vowels + " vowels");
  }
  public static void main(String[] args) {
    WordCount x = new WordCount("NOTEBOOK");
    x.count();
    x.display();
  }
}
