class Convert {
  int number;
  Convert(int n) {
    number = n;
  }
  int toBase(int n) {
    if (n == 0) {
      return 0;
    }
    return n % 8 + 10 * toBase(n / 8);
  }
  void show() {
    System.out.println(number + " is " + toBase(number) + " in base 8");
  }
  public static void main(String[] args) {
    Convert c = new Convert(47);
    c.show();
  }
}
